def flatten(iterable):
    result = []
    for item in iterable:
        if isinstance(item, list):
            # If the item is a list, recursively flatten it and extend the current result.
            result.extend(flatten(item))
        elif item is not None:
            # If the item is not a list and is not null-like (None in Python),
            # append it to the result.
            result.append(item)
    return result
